export function hallWinnerCell(r,{esc,fmt}){return `<b>${esc(r.lastWinner||'—')}</b>${r.lastWinner?`<small>${fmt(r.lastWinnerScore)} skor</small>`:''}`}
export function hallRecordCell(r,{esc,fmt}){return r.highestScore?`<b>${esc(r.recordName||'Önceki rekor')}</b><small>🏆 ${fmt(r.highestScore)} skor</small>`:'—'}
export function hallHero(rooms,{esc,fmt,skinEmoji}){const best=[...rooms].filter(r=>r.highestScore>0).sort((a,b)=>b.highestScore-a.highestScore)[0];const skin=best?.recordSkin||'',custom=/^custom-[a-f0-9]{24}$/.test(skin),emoji=skinEmoji(skin),color=/^#[a-f0-9]{6}$/i.test(best?.recordColor||'')?best.recordColor:'#202a46';return `<section class="hall-neon-hero"><div class="hall-neon-shards" aria-hidden="true"></div><h2>Onur Tablosu</h2><div class="hall-champion-label"><span>EN İYİ SKOR</span><strong>${best?fmt(best.highestScore):'—'}</strong><b>${best?esc(best.recordName||'Oyuncu'):'İlk şampiyon bekleniyor'}</b><small>${best?esc(best.id):'Turu kazan, zirveye adını yaz.'}</small></div><div class="hall-neon-ring"><div class="hall-champion-skin" style="background-color:${color}" role="img" aria-label="${best?esc(best.recordName||'Oyuncu')+' · Rekor alınırken kullanılan skin':'Henüz rekor yok'}">${custom?`<img src="/skins/${skin.slice(7)}.webp" alt="Rekor sahibinin skini" width="210" height="210">`:emoji?`<span>${esc(emoji)}</span>`:`<span class="hall-skin-fallback">${best?esc((best.recordName||'?').slice(0,1)):'🏆'}</span>`}</div></div></section>`}
